"const fs = require('fs');

const targets = JSON.parse(fs.readFileSync('target_companies.json', 'utf8'));

// Clean name function
function cleanCompanyName(name) {
  return name
    .replace(/\(주\)|\(유한\)|\(유책\)|\(합자\)|\(사\)/g, '')
    .replace(/주식회사|유한회사/g, '')
    .trim();
}

async function searchBiznoForCompany(item) {
  const cName = cleanCompanyName(item.name);
  // 1st attempt: area=부산 & query=cName
  // 2nd attempt: query=cName
  const searchUrls = [
    `https://bizno.net/?area=%EB%B6%80%EC%82%B0&query=${encodeURIComponent(cName)}`,
    `https://bizno.net/?query=${encodeURIComponent(cName)}`
  ];

  for (const url of searchUrls) {
    try {
      const res = await fetch(url, {
        headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)' }
      });
      const html = await res.text();
      const postListIdx = html.indexOf('post-list');
      if (postListIdx === -1) continue;

      const sidebarIdx = html.indexOf('class="col-lg-4 sidebar"');
      const searchSection = sidebarIdx !== -1 
        ? html.substring(postListIdx, sidebarIdx) 
