"async function check(name) {
  const url = `https://bizno.net/?query=${encodeURIComponent(name)}`;
  const res = await fetch(url, { headers: { 'User-Agent': 'Mozilla/5.0' } });
  const html = await res.text();
  const postListMatch = html.match(/<div class="col-lg-8 post-list">([\s\S]*?)<\/div>\s*<div class="col-lg-4 sidebar">/);
  if (!postListMatch) return console.log(name, 'no post list');
  const items = postListMatch[1].split('class="single-post');
  console.log(`=== ${name} (${items.length - 1} items) ===`);
  for (let i = 1; i < items.length; i++) {
    const item = items[i];
    const art = item.match(/\/article\/(\d{10})/)?.[1];
    const title = item.match(/<h4>([^<]+)<\/h4>/)?.[1]?.trim() || '';
    const p = item.match(/<p>([\s\S]*?)<\/p>/)?.[1]?.replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim() || '';
    const h5s = [...item.matchAll(/<h5>([^<]+)<\/h5>/g)].map(m => m[1].trim());
    console.log(`- art: ${art}, title: ${title}, addr: ${p}, h5s: ${JSON.stringify(h5s)}`);
  }
}

