"const fs = require('fs');
const path = require('path');

const targets = JSON.parse(fs.readFileSync('target_companies.json', 'utf8'));
const corpSet = new Map(targets.map(t => [t.corpNo.replace(/[^0-9]/g, ''), t]));

console.log(`Searching ${corpSet.size} target corp numbers across local files...`);

const files = fs.readdirSync('.').filter(f => f.endsWith('.tsv') || f.endsWith('.csv') || f.endsWith('.json'));

for (const file of files) {
  if (file === 'target_companies.json') continue;
  try {
    const content = fs.readFileSync(file, 'utf8');
    for (const [cleanCorp, t] of corpSet.entries()) {
      if (content.includes(t.corpNo) || content.includes(cleanCorp)) {
        console.log(`[MATCH in ${file}] ${t.seq} ${t.name} (Corp: ${t.corpNo})`);
      }
    }
  } catch (e) {}
}

// Also check 'data' folder
if (fs.existsSync('data')) {
  const dataFiles = fs.readdirSync('data').filter(f => f.endsWith('.tsv') || f.endsWith('.csv') || f.endsWith('.json') || f.endsWith('.txt'));
  for (const file of dataFiles) {
    try {
      const content = fs.readFileSync(path.join('data', file), 'utf8');
      for (const [cleanCorp, t] of corpSet.entries()) {
        if (content.includes(t.corpNo) || content.includes(cleanCorp)) {
          console.log(`[MATCH in data/${file}] ${t.seq} ${t.name} (Corp: ${t.corpNo})`);
        }
      }
    } catch (e) {}
  }
}
console.log('Search finished.');
"

