"const https = require('https');

async function searchBizno(query) {
  return new Promise((resolve, reject) => {
    const url = `https://bizno.net/?query=${encodeURIComponent(query)}`;
    https.get(url, { headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)' } }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => resolve(data));
    }).on('error', reject);
  });
}

async function run() {
  console.log('--- 1. Query: 해운대스위트호텔 ---');
  let html = await searchBizno('해운대스위트호텔');
  let matches = [...html.matchAll(/\/article\/(\d+)[^>]*>([\s\S]*?)<\/a>/g)];
  console.log('Matches for 해운대스위트호텔:', matches.length);
