  console.log('\n--- 2. Query: 영무파라드호텔 405호 ---');
  html = await searchBizno('해운대해변로298번길 25');
  matches = [...html.matchAll(/\/article\/(\d+)[^>]*>([\s\S]*?)<\/a>/g)];
  console.log('Matches for 해운대해변로298번길 25:', matches.length);
  for (const m of matches.slice(0, 10)) {
    console.log(m[1], m[2].replace(/<[^>]+>/g, '').trim());
  }

  console.log('\n--- 3. Query: 신유진 해운대 ---');
  html = await searchBizno('신유진');
  matches = [...html.matchAll(/\/article\/(\d+)[^>]*>([\s\S]*?)<\/a>/g)];
  console.log('Matches for 신유진:', matches.length);
  for (const m of matches.slice(0, 10)) {
